import{_ as r,y as n,a as s,o as i,a2 as t,D as a}from"./chunks/framework.DCcmcJcL.js";const f=JSON.parse('{"title":"Appearance","description":"","frontmatter":{},"headers":[],"relativePath":"appearance/themes.md","filePath":"appearance/themes.md","lastUpdated":1787288694000}'),h={name:"appearance/themes.md"};function l(c,e,p,d,g,u){const o=n("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=t('<h1 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h1><p>The appearance of your storefront defines its look and feel, and is a key factor in the first impression it makes on a visitor.</p><p>Appearance has its own area in the admin, separate from Settings. It holds two things: the <strong>themes</strong> available to your store, and the <strong>sections</strong> a theme&#39;s storefront is built from.</p><h2 id="themes" tabindex="-1">Themes <a class="header-anchor" href="#themes" aria-label="Permalink to &quot;Themes&quot;">​</a></h2><p>Go to <strong>Appearance &gt;&gt; Themes</strong> to see every theme, grouped so you can tell at a glance which are ready to use:</p><ul><li><strong>My Themes</strong> — themes installed on your store. Each shows whether it is active, and on which channels.</li><li><strong>Buy Themes</strong> — themes available from the marketplace, with links to preview or purchase them.</li></ul>',6)),a(o,{src:"/images/appearance/themes.png",alt:"Themes"}),e[1]||(e[1]=t('<p>From an installed theme you can:</p><ul><li><strong>Customize</strong> — open the section editor for that theme.</li><li><strong>Activate</strong> — apply the theme to one or more channels. Before it is applied, you are shown what the change affects.</li></ul><h2 id="sections" tabindex="-1">Sections <a class="header-anchor" href="#sections" aria-label="Permalink to &quot;Sections&quot;">​</a></h2><p>A section is one block of the storefront — a product carousel, a banner slider, a footer, and so on. Sections belong to a <strong>theme</strong> and a <strong>channel</strong>, so the same theme customised on two channels keeps two independent sets.</p><p>Open <strong>Appearance &gt;&gt; Themes</strong>, then <strong>Customize</strong> on the theme you want to edit.</p><h3 id="the-editor" tabindex="-1">The editor <a class="header-anchor" href="#the-editor" aria-label="Permalink to &quot;The editor&quot;">​</a></h3><p>The editor shows the list of sections on the left and a live storefront preview on the right. Selecting a section opens its fields; the preview updates as you edit, so you can see the result before anyone else does.</p><ul><li><strong>Reorder</strong> — drag a section by its handle to change where it appears.</li><li><strong>Switch on or off</strong> — use the toggle on the row.</li><li><strong>Duplicate</strong> or <strong>Delete</strong> — from the row&#39;s menu.</li><li><strong>Change locale or channel</strong> — from the selectors at the top. Each combination is edited separately.</li><li><strong>Change device</strong> — preview the storefront at desktop, tablet or mobile width.</li></ul>',8)),a(o,{src:"/images/appearance/section-editor.png",alt:"Section Editor"}),e[2]||(e[2]=t('<h3 id="nothing-goes-live-until-you-publish" tabindex="-1">Nothing goes live until you publish <a class="header-anchor" href="#nothing-goes-live-until-you-publish" aria-label="Permalink to &quot;Nothing goes live until you publish&quot;">​</a></h3><p>Every change is held as an <strong>unsaved change</strong> until you publish it. This applies to everything: editing content, switching a section on or off, and reordering.</p><p>The header shows how many sections are holding unsaved changes, and each affected row is marked. From there you can:</p><ul><li><strong>Publish</strong> — send the changes to the storefront.</li><li><strong>Discard</strong> — throw them away and return to what is currently live.</li></ul><p>A newly created section is switched off and counts as unsaved, so an empty section is never shown to shoppers before it has been built.</p><h3 id="creating-a-section" tabindex="-1">Creating a section <a class="header-anchor" href="#creating-a-section" aria-label="Permalink to &quot;Creating a section&quot;">​</a></h3><p><strong>Step 1:</strong> In the editor, click the <strong>+</strong> button beside the section list.</p><p><strong>Step 2:</strong> Choose the section type, give it a name, and save.</p>',8)),a(o,{src:"/images/appearance/create-section.png",alt:"Create Section"}),e[3]||(e[3]=t('<p><strong>Step 3:</strong> The section is added, switched off, and opened for editing. Fill in its fields, then <strong>Publish</strong> when you are ready for it to appear.</p><h2 id="section-types" tabindex="-1">Section types <a class="header-anchor" href="#section-types" aria-label="Permalink to &quot;Section types&quot;">​</a></h2><h3 id="product-carousel" tabindex="-1">Product Carousel <a class="header-anchor" href="#product-carousel" aria-label="Permalink to &quot;Product Carousel&quot;">​</a></h3><p>Shows products in a responsive carousel.</p><p><strong>Title:</strong> The heading shown above the carousel. <strong>Filters:</strong> Choose which products appear and in what order — for example by sort order, limit, category, or whether a product is new or featured.</p><h3 id="category-carousel" tabindex="-1">Category Carousel <a class="header-anchor" href="#category-carousel" aria-label="Permalink to &quot;Category Carousel&quot;">​</a></h3><p>Shows categories in a responsive carousel.</p><p><strong>Filters:</strong> Choose which categories appear and in what order — for example by parent, status, or limit.</p><h3 id="image-carousel" tabindex="-1">Image Carousel <a class="header-anchor" href="#image-carousel" aria-label="Permalink to &quot;Image Carousel&quot;">​</a></h3><p>A slider or banner area. Add a slide at a time, each with:</p><p><strong>Title:</strong> The slide title. <strong>Link:</strong> Where the slide points. <strong>Image:</strong> The slide image. A resolution of <strong>1920 × 700</strong> is recommended.</p><h3 id="static-content" tabindex="-1">Static Content <a class="header-anchor" href="#static-content" aria-label="Permalink to &quot;Static Content&quot;">​</a></h3><p>A free-form block of your own markup.</p><p><strong>HTML:</strong> The content itself. <strong>CSS:</strong> Styles for the block.</p><p>Both are cleaned before they are saved, so scripts and unsafe markup are stripped. Images used inside the HTML can be uploaded from the editor.</p><h3 id="footer-links" tabindex="-1">Footer Links <a class="header-anchor" href="#footer-links" aria-label="Permalink to &quot;Footer Links&quot;">​</a></h3><p>The storefront footer&#39;s link columns. Each column takes a set of links with a title and a URL.</p><p>A channel shows <strong>one footer links section</strong>, so once a channel has one, the type is no longer offered.</p><h3 id="services-content" tabindex="-1">Services Content <a class="header-anchor" href="#services-content" aria-label="Permalink to &quot;Services Content&quot;">​</a></h3><p>The service promises shown across the storefront — free delivery, returns, and similar. Each entry takes a title, a description, and an icon.</p><p>Because this section and the footer are drawn on every page rather than just the home page, publishing a change to either refreshes the whole storefront cache.</p><h2 id="upgrading-from-an-earlier-version" tabindex="-1">Upgrading from an earlier version <a class="header-anchor" href="#upgrading-from-an-earlier-version" aria-label="Permalink to &quot;Upgrading from an earlier version&quot;">​</a></h2><p>If you used <strong>Settings &gt;&gt; Themes</strong> before, that screen has moved. Theme customizations are now sections, and they live under <strong>Appearance</strong>. Existing customizations are carried over automatically — you do not need to recreate them.</p>',23))])}const b=r(h,[["render",l]]);export{f as __pageData,b as default};
